oad.GameName,Area=Game.CurrentlyLoadedArea};Game.SaveManager.Add(save);Loader.Descriptor=save;Loader.WorkingPath=ArchivePath;Loader.State=WorkingFixtureLoadState.LoadedAndVerified;Loader.LoadCallbackObserved=true;Authority.AdmittedNativeLoadRequests=Auth.AuthorizedLoadCount=1;Persistence.LoadedArchive.CampaignId=p.GameId;Persistence.LoadedArchive.AreaId=R.PersistenceLoad.Area;if(Seed){Persistence.LoadedArchive=null;Persistence.LoadedArchiveKind=MountedSaveReadKind.Missing;Persistence.LoadedArchiveCanRestore=false;}Probe.LoadObserved();}
